  function supportAllowed(){return !!actor()&&(admin()||users().some(u=>u.uid!==actor().uid&&canCoach(u.uid)));}
  function ownWeek(uid){return (((data.weeks||{})[uid||actor().uid]||{})[week]||{});}
  function profile(uid){return data.profiles[uid]||{};}
