  function teamGoalOwner(){const a=actor();return admin()||users().some(u=>(data.access[u.uid]||{}).leaderUid===a.uid)?a.uid:(data.access[a.uid]||{}).leaderUid||a.uid;}
  function teamUsers(){if(admin())return users();const a=actor(),lead=teamGoalOwner();return users().filter(u=>u.uid===a.uid||u.uid===lead||(data.access[u.uid]||{}).leaderUid===lead);}
  function readable(){return users().filter(u=>u.uid===actor().uid||canCoach(u.uid));}
